            "ar": "لذلك يرى علماء النفس أن إدراك الوقت الشخصي لا يتعلق بعدد الدقائق الفعلية، بل بعدد المعلومات الجديدة التي يتوجب على الدماغ معالجتها في فترة زمنية محددة.",
