            "ar": "وعلى امتداد طريق صانعي الساعات الذي يبلغ طوله حوالي 200 كيلومتر، يمكن للمرء في 38 محطة زيارة أشهر مصانع الساعات والعديد من المتاحف المتخصصة فيها.",
