            "ar": "ولكني حين أفكر في الرياضة أو الفن، أعتقد أنه لا بد من وجود الموهبة حقاً، ومع ذلك يُتوقع أيضاً من الرياضيين المحترفين أن يتدربوا بانتظام وقسوة. – مايسترو",
