            "id": "text-08-p2-s1",
            "de": "Vor mehr als 500 Jahren reiste man eher selten. Reisen war hart und gefährlich. Wenn, dann waren vor allem Männer unterwegs.",
            "ar": "قبل أكثر من 500 عام، كان السفر نادراً وشاقاً ومحفوفاً بالمخاطر، وحين كان يحدث، كان الرجال هم من يسافرون غالباً.",
