    "exercises": [
      {
        "id": "ex-08-01",
        "type": "تسلسل تاريخي (Buch S. 40–41)",
        "prompt": "Was war der Hauptgrund für Bildungsreisen im 18. Jahrhundert?",
        "options": [
          {
            "text": "Reiche Adlige wollten Kunst, Kultur und Sprachen Europas (z.B. in Italien) intensiv kennenlernen."
          },
          {
            "text": "Man wollte billig am Strand campen."
          },
          {
            "text": "Die Menschen mussten vor Bären und Wölfen fliehen."
          }
        ],
        "correctIndex": 0,
        "explanation": "كانت الرحلات التعليمية في القرن الثامن عشر تستهدف الاطلاع على الحضارات والفنون والآثار الأوروبية، خاصة في إيطاليا وفرنسا."
      }
    ]
